#!/data/data/com.termux/files/usr/bin/bash
set -e

MANIFEST="app/src/main/AndroidManifest.xml"
STRINGS="app/src/main/res/values/strings.xml"
GALLERY_ACTIVITY="app/src/main/java/com/android/gallery3d/app/GalleryActivity.java"

echo "== Adicionando permissoes modernas de midia ao AndroidManifest.xml =="
if ! grep -q "READ_MEDIA_IMAGES" "$MANIFEST"; then
  sed -i 's#<uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE" />#<uses-permission android:name="android.permission.READ_EXTERNAL_STORAGE" android:maxSdkVersion="32" />\n    <uses-permission android:name="android.permission.READ_MEDIA_IMAGES" />\n    <uses-permission android:name="android.permission.READ_MEDIA_VIDEO" />\n    <uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE" android:maxSdkVersion="29" />#' "$MANIFEST"
else
  echo "Ja tem READ_MEDIA_IMAGES, pulando."
fi

echo "== Conferindo permissoes no manifest =="
grep -n "uses-permission" "$MANIFEST"

echo "== Adicionando string no_permission_message =="
if ! grep -q "no_permission_message" "$STRINGS"; then
  sed -i 's#<string name="no_such_item">Couldn\\'"'"'t find item.</string>#<string name="no_such_item">Couldn\\'"'"'t find item.</string>\n    <string name="no_permission_message">Photo and video access is required to use this app.</string>#' "$STRINGS"
else
  echo "String ja existe, pulando."
fi
grep -n "no_permission_message" "$STRINGS"

echo "== Restaurando GalleryActivity.java com fluxo de permissao em runtime =="
mkdir -p "$(dirname "$GALLERY_ACTIVITY")"
base64 -d > "$GALLERY_ACTIVITY" << 'B64_EOF'

B64_EOF

echo "== Conferindo tamanho do GalleryActivity.java =="
wc -l "$GALLERY_ACTIVITY"

echo "== Fix concluido =="
